<script lang="ts">
	let { types, tags, selectedType, selectedTag } = $props<{ types: string[]; tags: string[]; selectedType?: string; selectedTag?: string }>();
	const hrefFor = (type?: string, tag?: string) => { const params = new URLSearchParams(); if (type) params.set('type', type); if (tag) params.set('tag', tag); const query = params.toString(); return query ? `/library?${query}` : '/library'; };
</script>
<div class="space-y-6"><div><h2 class="mb-3 text-sm font-medium text-zinc-400">Type</h2><div class="flex flex-wrap gap-2"><a href={hrefFor(undefined, selectedTag)} class="rounded-full px-3 py-1 text-sm {selectedType ? 'bg-zinc-900 text-zinc-400' : 'bg-brand-lime text-black'}">All</a>{#each types as type}<a href={hrefFor(type, selectedTag)} class="rounded-full px-3 py-1 text-sm {selectedType === type ? 'bg-brand-lime text-black' : 'bg-zinc-900 text-zinc-400'}">{type}</a>{/each}</div></div><div><h2 class="mb-3 text-sm font-medium text-zinc-400">Tag</h2><div class="flex flex-wrap gap-2"><a href={hrefFor(selectedType, undefined)} class="rounded-full px-3 py-1 text-sm {selectedTag ? 'bg-zinc-900 text-zinc-400' : 'bg-brand-lime text-black'}">All</a>{#each tags as tag}<a href={hrefFor(selectedType, tag)} class="rounded-full px-3 py-1 text-sm {selectedTag === tag ? 'bg-brand-lime text-black' : 'bg-zinc-900 text-zinc-400'}">{tag}</a>{/each}</div></div></div>
